function espnImplied(sb){                // ESPN scoreboard -> {TEAM:{imp,opp,oppImp,status}}
  const out={};const fix=a=>a==="WSH"?"WAS":a;
  ((sb&&sb.events)||[]).forEach(e=>{const c=e.competitions&&e.competitions[0];if(!c)return;const o=(c.odds||[])[0];
    const t={};(c.competitors||[]).forEach(x=>t[x.homeAway]=fix(x.team.abbreviation));
    const st=(c.status&&c.status.type&&c.status.type.state)||"";
    if(!o||o.overUnder==null||o.spread==null){if(t.home)out[t.home]={opp:t.away,oppImp:null,status:st};if(t.away)out[t.away]={opp:t.home,oppImp:null,status:st};return;}
    const hi=o.overUnder/2-o.spread/2,ai=o.overUnder/2+o.spread/2;
    out[t.home]={imp:hi,opp:t.away,oppImp:ai,status:st};out[t.away]={imp:ai,opp:t.home,oppImp:hi,status:st};});
  return out;}
