function myPickIn(r){return (r-1)*state.teams+(r%2===1?state.slot:state.teams+1-state.slot);}
function nextPicks(pickNum){const out=[];for(let r=1;r<=state.rounds;r++){const p=myPickIn(r);if(p>=pickNum)out.push(p);if(out.length===2)break;}return out;}


function slotOfPick(pk){const r=Math.floor((pk-1)/state.teams)+1;const i=(pk-1)%state.teams;return r%2===1?i+1:state.teams-i;}
// v3.4: how much earlier (in picks) a position tends to vanish given who picks between now and my next turn
function riskShift(pos,pickNum,np){let t=0;for(let pk=pickNum;pk<np&&pk<pickNum+state.teams*2;pk++){const nm=state.oppBySlot[slotOfPick(pk)];if(!nm)continue;const o=OPP_TEND[nm];if(o&&o[pos]<0)t+=(-o[pos]);}return Math.min(8,Math.round(t/3));}

