function searchNameFor(n){
  const m=/^(.+?)\s+DEF$/.exec(n);
  if(m){const nick=m[1].trim();return DEF_CITY[nick]||nick;}
  // if another draftable player shares this last name, the full name is required for a unique match
  const ln=n.split(" ").slice(-1)[0];
  const shared=(typeof P!=="undefined")&&P.filter(x=>x.name!==n&&x.name.split(" ").slice(-1)[0]===ln).length>0;
  if(shared)state.requireFullName=true;
  return n;
}
function findSearchBox(){
  const sels=['input[placeholder*="Find player" i]','input[placeholder*="Search" i]',
              'input[type="search"]','input[class*="search" i]'];
  for(const s of sels){const el=document.querySelector(s);if(el&&el.offsetParent!==null)return el;}
  return null;
}
function setNativeValue(el,val){
  const proto=Object.getPrototypeOf(el);
  const d=Object.getOwnPropertyDescriptor(proto,"value");
  if(d&&d.set)d.set.call(el,val); else el.value=val;
  el.dispatchEvent(new Event("input",{bubbles:true}));
  el.dispatchEvent(new Event("change",{bubbles:true}));
}
function norm2(s){return (s||"").toLowerCase().replace(/[^a-z]/g,"");}
function nameMatches(rowText,player){
  const a=norm2(rowText), p=player.trim().split(" ");
  const ln=norm2(p[p.length-1]), fn=norm2(p[0]);
  return a.includes(ln)&&(a.includes(fn)||a.includes(fn[0]));
}
// the player rows in Sleeper's draft list
function playerRows(){
  return Array.from(document.querySelectorAll('div.player-rank-item2, div[class*="player-rank-item"]'));
}
function rowNameText(row){
  const n=row.querySelector('.name');
  return n?n.innerText:row.innerText;
}
function findRowFor(name){
  for(const r of playerRows()){ if(nameMatches(rowNameText(r),name)) return r; }
  return null;
}
function findAddControl(row){
  return row.querySelector('.draft-button')||row.querySelector('.draft-button-wrapper')||
         row.querySelector('[class*="draft-button"]')||null;
}
function realClick(el){
  const r=el.getBoundingClientRect();
  const opts={bubbles:true,cancelable:true,view:window,clientX:r.left+r.width/2,clientY:r.top+r.height/2};
  el.dispatchEvent(new MouseEvent("pointerdown",opts));
  el.dispatchEvent(new MouseEvent("mousedown",opts));
  el.dispatchEvent(new MouseEvent("pointerup",opts));
  el.dispatchEvent(new MouseEvent("mouseup",opts));
  el.dispatchEvent(new MouseEvent("click",opts));
}
function nextPickFor(slot){
  for(let r=1;r<=state.rounds;r++){
    const pk=(r-1)*state.teams+(r%2?slot:state.teams+1-slot);
    if(pk>state.lastCount)return pk;
  }
  return -1;
}
function setAssistErr(m){state.assistErr=m;if(m){clearTimeout(state._aeT);state._aeT=setTimeout(()=>{state.assistErr="";render();},6000);}}
function cancelPending(){state.pending=null;state.pendingT=0;render();}
// wait for the virtualized list to render the filtered row, then click
function fireAutopick(tries){
  const p=state.pending;if(!p)return;
  tries=tries||0;
  const row=findRowFor(p.name);
  if(!row){
    if(tries<10){setTimeout(()=>fireAutopick(tries+1),200);return;}
    setAssistErr("row not found: "+p.name);state.pending=null;render();return;
  }
  if(!nameMatches(rowNameText(row),p.name)){setAssistErr("name mismatch, aborted");state.pending=null;render();return;}
  const ctrl=findAddControl(row);
  if(!ctrl){setAssistErr("draft-button not found");state.pending=null;render();return;}
  try{realClick(ctrl);state.assistErr="";state.pickMsg="drafted "+p.name;setTimeout(()=>{state.pickMsg="";render();},2500);}
  catch(e){setAssistErr("click failed");}
  state.pending=null;render();
}
function maybeAssist(c){
  if(!state.assist)return;
  if(state.status&&state.status!=="drafting")return;   // lobby/paused/complete: stand down
  if(!playerRows().length)return;                       // player list not rendered yet
  if(!c.top||!c.top.length)return;
  if(c.pickNum!==nextPickFor(state.slot))return;
  if(state.lastAssisted===c.pickNum)return;
  const box=findSearchBox();
  if(!box){setAssistErr("search box not found");return;}
  state.assistErr="";
  setNativeValue(box,searchNameFor(c.top[0].name));
  state.lastAssisted=c.pickNum;
  state.pending={name:searchNameFor(c.top[0].name),pick:c.pickNum};
  state.pendingT=3;render();
  const tick=setInterval(()=>{
    if(!state.pending){clearInterval(tick);return;}
    state.pendingT--;
    if(state.pendingT<=0){clearInterval(tick);fireAutopick(0);}
    else render();
  },1000);
}
const QB_SORT=P.filter(x=>x.pos==="QB").sort((a,b)=>b.pts-a.pts);
const QB_TOP=QB_SORT[0]||{name:""};const QB_GAP=QB_SORT.length>1?QB_SORT[0].pts-QB_SORT[1].pts:0;
const ELITE_TE=P.filter(x=>x.pos==="TE").sort((a,b)=>b.pts-a.pts).slice(0,2).map(x=>x.name);
const ELITE_TE_AVG=(()=>{const v=ELITE_TE.map(n=>TE_PRIOR_PPG[n]).filter(x=>x!=null);return v.length?v.reduce((a,b)=>a+b,0)/v.length:0;})();
function coach(){
  const QB_LATE=Math.max(9,state.rounds-4);
  const pickNum=state.taken.size+1;
  const round=Math.min(state.rounds,Math.floor((pickNum-1)/state.teams)+1);
  const counts={QB:0,RB:0,WR:0,TE:0};state.mine.forEach(m=>counts[m.pos]=(counts[m.pos]||0)+1);
  const myQB=state.mine.find(m=>m.pos==="QB");
  const stackSet=new Set(myQB?(STACKS[myQB.name]||[]):[]);
  const vetRBs=state.mine.filter(m=>VETRISK.has(m.name)&&m.pos==="RB").length;
  const nx=nextPicks(pickNum).concat([999,999]);const np=nx[0],npa=nx[1];
  const cands=P.filter(p=>!state.taken.has(p.id)).filter(p=>{
    if(MY_FADE[p.name])return false;                       // your call, no exceptions
    if(AVOID[p.name]&&!MY_FAVOR[p.name]&&p.pos!=="QB")return false;
    if(p.pos==="TE"&&counts.TE>0)return false;
    if(p.pos==="QB"&&counts.QB>0)return false;   // v7.7: hard cap. The validated backtest never drafts QB2; stream in-season instead.
    if(p.pos==="QB"){
      // v10.3: in 8-team 1QB the weekly free-agent QB outscored the drafted QB8 both years (2024: 21.5 vs 17.5, 2025: 20.0 vs 18.1).
      // R5-8 QBs returned -15/-17 pts vs that free QB. Only the monopoly QB (Vegas pts 30+ over QB2) earned his pick (+52/+57).
      if(p.name===QB_TOP.name&&QB_GAP>=QB_MONO_GAP)return round>=3;
      return round>=QB_LATE;}
    if(p.pos==="TE"){
      if(ELITE_TE.includes(p.name))return round>=2&&round<=5;
      return round>=9;}
    return true;});
  const apool=P.filter(x=>!state.taken.has(x.id)&&!MY_FADE[x.name]&&(!AVOID[x.name]||MY_FAVOR[x.name]));
  const bestLater=(pos,after)=>{let b=0;for(const x of apool){if(x.pos===pos&&x.adp>=after-2&&x.pts>b)b=x.pts;}return b;};
  const repl={};["QB","RB","WR","TE"].forEach(ps=>{const base=(np<=pickNum+1&&npa<900?npa:(np<900?np:pickNum+state.teams));repl[ps]=bestLater(ps,base+riskShift(ps,pickNum,np));});
  // v3.2: how far below target depth each position is, for THIS roster (0..1, higher = needier)
  const need={};["QB","RB","WR","TE"].forEach(ps=>{const have=counts[ps]||0;let tgt=ROSTER_NEED[ps];if(ps==="RB"&&state.rounds>=16)tgt=5;if(state.teams>=10&&ps==="WR")tgt=4;need[ps]=Math.max(0,(tgt-have)/tgt);});
  const scored=cands.map(p=>{
    const marginal=p.pts-(repl[p.pos]||p.pts*0.55);
    // v3.2: risk-adjust the points by position volatility (shave the bustier positions slightly)
    const riskAdj=p.pts*POSVOL[p.pos]*0.3;
    let s=marginal*3.5+p.pts*0.2-riskAdj;
    // v3.2: balance nudge — reward filling a thin position, softly (caps at ~+18 so it never overrides a big marginal gap)
    s+=need[p.pos]*38*(round<=10?1:0.4);
    s+=Math.max(-20,Math.min(30,p.edge))*0.1;
    if(round<=3&&p.pos==="RB")s+=8;
    if(MY_FAVOR[p.name])s+=25;
    if(BOOM.has(p.name))s+=15;   // v7.6: verified on real 2024-tags->2025-outcomes backtest (+4.4pp win rate vs 10) // spike-week tiebreaker (real 2025 weekly data)
    if(FLAT.has(p.name)&&!MY_FAVOR[p.name]&&!MY_FAVOR_SOFT[p.name])s-=(round>=11?16:8); // hollow totals; worse in ceiling-only rounds // league: RB-heavy builds outscore; WRs replaceable on waivers
    if(p.adp>round*state.teams+12)s-=25;
    if(round>=9&&p.pos==="RB"&&counts.RB<4)s+=30;
    if(round>=11&&p.pos==="WR"&&p.edge>=18)s+=25;
    if(round>=11&&FLOORS.has(p.name))s-=40;
    if(round>=12&&CUFFS.has(p.name)&&counts.RB>=3)s+=20;
    if(stackSet.has(p.name)&&!AVOID[p.name]&&!MY_FADE[p.name])s+=22;
    if(VETRISK.has(p.name)&&p.pos==="RB"&&vetRBs>=1)s-=30;
    // League-tuned: rounds 4-8 have bled on declining veteran name brands (Kamara R4->RB46, Conner R6->RB77, Ridley R7->WR117). Fade aging vets in that window.
    if(round>=4&&round<=8&&VETRISK.has(p.name))s-=22;
    // v7.5: removed the June-era +60 Allen bonus. The QB tier compressed (four QBs at 284-289),
    // so the marginal term alone now prices his edge correctly; the flat bonus double-counted it.
    // The validated backtest config never had this bonus.
    if(p.pos==="TE"&&counts.TE===0&&round>=3)s+=40;
    // v10.3 TE tiebreak: prior-year PPR ppg beyond ADP predicted TE ppg (r=0.33, n=25, 2024-25). Games missed did NOT (r=-0.08).
    // 2026 case: McBride 18.9 vs Bowers 14.7 prior ppg at equal Vegas pts (182 vs 180).
    if(p.pos==="TE"&&ELITE_TE.includes(p.name)&&TE_PRIOR_PPG[p.name]!=null)s+=Math.max(-8,Math.min(8,(TE_PRIOR_PPG[p.name]-ELITE_TE_AVG)*2));
    if(p.adp<npa-4)s+=8;
    return Object.assign({},p,{s,m:Math.round(marginal),stack:stackSet.has(p.name),urgent:(p.adp<np-1)&&(p.m>=25),lag:p.adp<=pickNum-10});});
  scored.sort((a,b)=>b.s-a.s);
  const tips=[];
  const haveTE=counts.TE>0,haveQB=counts.QB>0;
  if(round<=2)tips.push("R1-2: best RB/WR. Lean RB.");
  if(round>=3&&round<=4){if(!haveTE)tips.push("MONOPOLY: McBride/Bowers if up.");if(!haveQB)tips.push(QB_GAP>=QB_MONO_GAP?("QB: only "+QB_TOP.name.split(" ").pop()+" (+"+Math.round(QB_GAP)+" over QB2). Everyone else waits til R"+QB_LATE+"."):"QB: no monopoly QB this year. Wait til R"+QB_LATE+".");}
  if(round>=5&&round<=8){
    const win=P.filter(x=>!state.taken.has(x.id)&&!MY_FADE[x.name]&&x.pos!=="QB"&&x.edge>=10&&x.pts>=140)
      .sort((a,b)=>b.edge-a.edge).slice(0,6).map(x=>x.name.split(" ").pop());
    if(win.length)tips.push("VALUE WINDOW: "+win.join(", ")+". No TEs.");
  }
  if(round>=5&&!haveQB&&round<QB_LATE)tips.push("NO QB til R"+QB_LATE+". Free-agent QBs beat the drafted QB8 in 2024 and 2025.");
  if(round>=9&&round<=10){if(counts.RB<4)tips.push("RB DEPTH: only "+counts.RB+" RBs. Grab a back.");if(!haveTE)tips.push("TE now: Kelce/Kittle/Gadsden.");}
  if(round>=11&&round<=13)tips.push("CEILING ONLY. No floor vets (Meyers rule). Cuffs OK.");
  if(round>=14)tips.push("DEF + K last two picks. DEF ADP predicts nothing (r -0.04/-0.02)."+(state.kMode==="inverted"?" K is INVERTED here: misses score.":""));
  if(haveTE)tips.push("NEVER a 2nd TE.");
  if(haveQB&&(state.rounds-state.mine.length)>4)tips.push("One QB til the end (2nd QB = final skill rounds only)."+(stackSet.size?" Stack: "+myQB.name+"'s guys boosted.":""));
  if(vetRBs>=2)tips.push("WARNING: "+vetRBs+" age-cliff RBs. Cap it.");
  const haveDEF=state.mine.some(m=>m.pos==="DEF"),haveK=state.mine.some(m=>m.pos==="K");
  const remaining=state.rounds-state.mine.length;
  if(remaining<=2){
    const wantPos=(!haveDEF&&remaining<=2)?"DEF":((!haveK&&remaining<=1)||(!haveK&&haveDEF))?"K":null;
    if(wantPos){
      const nick=s=>s.replace(/ DEF$/,"").trim().split(" ").pop().toLowerCase();
      const takenNick=new Set([...state.takenNames].map(n=>n.trim().split(" ").pop().toLowerCase()));
      const dkl=dkList(wantPos);
      const dk=dkl.list.filter(d=>!state.takenNames.has(norm(d[0]))&&!(d[1]==="DEF"&&takenNick.has(nick(d[0]))));
      const top=dk.slice(0,3).map((d,i)=>({id:"dk"+i,name:d[0],pos:d[1],vrank:i+1,pts:d[2]||0,adp:0,edge:0,s:999-i,stack:false,urgent:false,lag:false}));
      if(top.length)return{pickNum,round,counts,top,tips:[dkl.note,...tips],np,npa};
    }
  }
  const top3=scored.slice(0,3);
  const boomAvail=cands.filter(x=>BOOM.has(x.name)&&x.pos!=="QB"&&!MY_FADE[x.name]&&!top3.some(t=>t.name===x.name)).sort((a,b)=>b.pts-a.pts)[0]||null;
  const myGuys=MY_GUYS.map(nm=>P.find(x=>x.name===nm)).filter(x=>x&&!state.taken.has(x.id)&&!top3.some(t=>t.name===x.name)&&(x.adp-np)<=24)
    .map(x=>({name:x.name,pts:x.pts,now:x.adp<=np+1,adp:x.adp,d:top3.length?x.pts-top3[0].pts:0}))
    .sort((a,b)=>(b.now?1:0)-(a.now?1:0)||b.pts-a.pts).slice(0,4);
  return{pickNum,round,counts,top:top3,tips,np,npa,boomAvail,myGuys};
}

// v10.3 K/DEF ranking. DEF: week-1 Vegas line (DEF pts = 17.34 - 0.462 x opp implied), else last year's DEF ppg.
// K normal scoring: accuracy tiers. K inverted: last year's miss points per game (weak: YoY r -0.04 in 2024, +0.44 in 2025).
function dkList(pos){
  if(pos==="DEF"){
    const im=state.wk1Imp;const rows=Object.keys(TEAM_NICK).map(t=>{const g=im&&im[t];
      const e=(g&&g.oppImp!=null)?defExp(g.oppImp):null;return [TEAM_NICK[t]+" DEF","DEF",e!=null?+e.toFixed(1):(DEF_PPG_PRIOR[t]||0),t,g];});
    const useWk1=im&&rows.some(r=>r[4]&&r[4].oppImp!=null);
    rows.sort((a,b)=>b[2]-a[2]);
    return {list:rows,note:useWk1?"AUTO: DEF by week-1 Vegas line (exp pts shown). Swap later only when opp implied is 22+.":"AUTO: DEF by last year's ppg (no week-1 lines yet). ADP predicts nothing."};}
  if(state.kMode==="inverted")return {list:K_INV_PRIOR.map(k=>[k[0],"K",k[2]]),note:"AUTO: INVERTED K (misses score). Ranked by last year's miss pts/g. Weak signal: take last pick, never stream."};
  return {list:DEFK.filter(d=>d[1]==="K"),note:"AUTO: Kicker round. Lock it and done."};}
function esc(t){return String(t).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}

