function mkcPos(){try{const v=localStorage.getItem("mkcPanelPos");return v?JSON.parse(v):null;}catch(e){return null;}}
function mkcSavePos(t,l){try{localStorage.setItem("mkcPanelPos",JSON.stringify({t,l}));}catch(e){}}
function mkcDrag(el,handle){
  if(!handle||handle.dataset.mkcDrag)return;handle.dataset.mkcDrag="1";
  handle.style.cursor="move";
  handle.addEventListener("mousedown",e=>{
    if(e.target.id==="mkc-s-tog")return;          // let the collapse arrow work
    e.preventDefault();
    const r=el.getBoundingClientRect();
    const ox=e.clientX-r.left, oy=e.clientY-r.top;
    function mv(ev){
      const l=Math.max(0,Math.min(window.innerWidth-r.width, ev.clientX-ox));
      const t=Math.max(0,Math.min(window.innerHeight-40, ev.clientY-oy));
      el.style.left=l+"px";el.style.top=t+"px";el.style.right="auto";
    }
    function up(){document.removeEventListener("mousemove",mv);document.removeEventListener("mouseup",up);
      const r2=el.getBoundingClientRect();mkcSavePos(Math.round(r2.top),Math.round(r2.left));}
    document.addEventListener("mousemove",mv);document.addEventListener("mouseup",up);
  });
}
// ---- inline verdict badges on Sleeper player rows ----
function mkcVerdictMap(){
  const m={};
  (S.wire||[]).forEach(r=>{m[r.n.toLowerCase()]={v:r.v,pts:r.pts};});
  // everything scanned but not in the top-6 still gets a verdict
  (S.allWire||[]).forEach(r=>{if(!m[r.n.toLowerCase()])m[r.n.toLowerCase()]={v:r.v,pts:r.pts};});
  return m;
}
function mkcTagRows(){
  try{
    const map=mkcVerdictMap();if(!Object.keys(map).length)return;
    const COL={CLAIM:"#2FE08A",LEAD:"#C58BFF",UPSIDE:"#5BA8FF",WATCH:"#FFC247",NO:"#5A6478"};
    const nodes=document.querySelectorAll("div,span,a");
    let budget=400;                       // cap tags per pass; rescan runs every 2s anyway
    for(const n of nodes){
      if(budget<=0)break;
      if(n.dataset&&n.dataset.mkcTagged)continue;
      if(n.children.length!==0)continue;   // player names live in leaf nodes; skip containers
      if(n.closest("#mkc-season,#mkc-panel"))continue;   // never tag our own UI
      const t=(n.textContent||"").trim();
      if(t.length<6||t.length>34)continue;
      const hit=map[t.toLowerCase()];
      if(!hit)continue;
      n.dataset.mkcTagged="1";budget--;
      const b=document.createElement("span");
      b.textContent=hit.v;
      b.style.cssText="margin-left:6px;padding:1px 5px;border-radius:3px;font:700 9px/1.4 -apple-system,sans-serif;color:#0F1420;background:"+COL[hit.v]+";vertical-align:middle";
      n.appendChild(b);
    }
  }catch(e){}
}
