  if(S.collapsed){el.innerHTML='<div style="padding:8px 12px;cursor:pointer;font-weight:800;color:#2FE08A" id="mkc-s-tog">SEASON COACH &#9656;</div>';document.getElementById("mkc-s-tog").onclick=()=>{S.collapsed=false;seasonRender();};return;}
